arguments.command:
mkdir -p tests/CheckoutPricing.UnitTests/Checkout src/CheckoutPricing.Application/Checkout
cat > src/CheckoutPricing.Application/Checkout/CalculatePayableTotal.cs <<'E'
namespace CheckoutPricing.Application.Checkout;

public enum CustomerTier { Gold }

public sealed record CalculatePayableTotalQuery(CustomerTier Tier, decimal OrderSubtotal);

public sealed class CalculatePayableTotalHandler
{
    public decimal Handle(CalculatePayableTotalQuery query) => query.OrderSubtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/Checkout/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application.Checkout;

namespace CheckoutPricing.UnitTests.Checkout;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void Gold_customer_receives_the_approved_discount()
    {
        var handler = new CalculatePayableTotalHandler();

        var payable = handler.Handle(new CalculatePayableTotalQuery(CustomerTier.Gold, 100.00m));

        Assert.Equal(95.00m, payable);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests --filter "FullyQualifiedName~LoyaltyDiscountTests" --verbosity quiet 2>&1 | grep -v '^\s*$' | head -25

